# Create the main Flask application
app = Flask(__name__)

# Create a Blueprint for users routes
from flask import Blueprint

users_bp = Blueprint('users', __name__)

# In-memory storage for demo purposes
users_data = {
    1: {'id': 1, 'name': 'Alice', 'email': 'alice@example.com'},
    2: {'id': 2, 'name': 'Bob', 'email': 'bob@example.com'},
}

next_user_id = 3

# Users routes
@users_bp.route('/', methods=['GET'])
def list_users():
    return jsonify(list(users_data.values()))

@users_bp.route('/<int:user_id>', methods=['GET'])
def get_user(user_id):
    if user_id not in users_data:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(users_data[user_id])

@users_bp.route('/', methods=['POST'])
def create_user():
    global next_user_id
    data = request.get_json()
    if not data or 'name' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    user = {
        'id': next_user_id,
        'name': data['name'],
        'email': data['email']
    }
    users_data[next_user_id] = user
    next_user_id += 1
    return jsonify(user), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    if user_id not in users_data:
        return jsonify({'error': 'User not found'}), 404

    data = request.get_json()
    if 'name' in data:
        users_data[user_id]['name'] = data['name']
    if 'email' in data:
        users_data[user_id]['email'] = data['email']

    return jsonify(users_data[user_id])

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    if user_id not in users_data:
        return jsonify({'error': 'User not found'}), 404

    deleted_user = users_data.pop(user_id)
    return jsonify(deleted_user)

# Register the users blueprint with /users prefix
app.register_blueprint(users_bp, url_prefix='/users')

# Root route
